            return money - (prices[i] + prices[i + 1])
    return money

def count_good_integers(num1, num2, min_sum, max_sum):
    MOD = 10**9 + 7

    def digit_sum(n):
        return sum(int(digit) for digit in str(n))

    def count_up_to(n):
        count = 0
        for i in range(1, n + 1):
            if digit_sum(i) <= max_sum:
                count += 1
        return count

    return (count_up_to(int(num2)) - count_up_to(int(num1) - 1) + MOD) % MOD

