def is_punishment_number(i):
    square = i * i
    square_str = str(square)

    def can_partition(s, target):
        if target == 0:
            return True
        if target < 0:
            return False
        for i in range(1, len(s) + 1):
            if can_partition(s[i:], target - int(s[:i])):
                return True
        return False

    return can_partition(square_str, i)

def punishment_number(n):
