def minCost(cost, time):
    n = len(cost)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if time[i - 1] >= j:
                dp[i][j] = min(dp[i - 1][j] + cost[i - 1], dp[i - 1][j - 1] + cost[i - 1])
            else:
                dp[i][j] = dp[i - 1][j]
    return dp[n][n]

