import math

def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def canTraverseAllPairs(nums):
    n = len(nums)
    if n == 1:
        return True

    prime_to_index = {}
    for i, num in enumerate(nums):
        if num in prime_to_index:
            return False
        prime_to_index[num] = i

    for i in range(n):
        for j in range(i + 1, n):
            if gcd(nums[i], nums[j]) > 1:
                return True
    return False

def smallest_string(s):
    n = len(s)
    for i in range(n):
        for j in range(i, n):
            if s[i] != 'a':
                s = s[:i] + chr(ord(s[i]) - 1) + s[i+1:j] + s[j+1:]
                break
        else:
            continue
        break
    return s

