def sorted_marble_positions(nums, moveFrom, moveTo):
    positions = set(nums)
    for src, dest in zip(moveFrom, moveTo):
        if src in positions:
            positions.remove(src)
            positions.add(dest)
    return sorted(positions)

def min_operations(num1, num2):
