def maximumSumQueries(nums1, nums2, queries):
    nums1.sort(reverse=True)
    nums2.sort(reverse=True)
    n = len(nums1)
    queries.sort(key=lambda x: (x[0], x[1]), reverse=True)

    result = []
    j = 0
    for x, y in queries:
        while j < n and nums1[j] < x:
            j += 1
        while j < n and nums2[j] < y:
            j += 1
        if j < n:
            result.append(nums1[j] + nums2[j])
        else:
            result.append(-1)

    return result

def sum_of_squares_of_special_elements(nums):
    n = len(nums)
    special_elements = [nums[i] for i in range(1, n + 1) if n % i == 0]
    return sum(x * x for x in special_elements)

def find_partition_value(nums):
    nums1 = [nums[0]]
    nums2 = [nums[1]]
    for i in range(2, len(nums)):
        if nums[i] < min(nums1 + nums2):
            nums1.append(nums[i])
        else:
            nums2.append(nums[i])
    return abs(max(nums1) - min(nums2))

def max_pairs(words):
    word_set = set(words)
    pairs = 0
    for word in words:
        if word[::-1] in word_set and word != word[::-1]:
            pairs += 1
            word_set.remove(word)
            word_set.remove(word[::-1])
    return pairs

def special_permutations(nums):
    MOD = 10**9 + 7
    n = len(nums)

    def count_permutations(nums, used):
        if len(used) == n:
            return 1
        count = 0
        for i in range(n):
            if not used[i]:
                if i > 0 and nums[i] % nums[i-1] != 0:
                    continue
                if i < n-1 and nums[i] % nums[i+1] != 0:
                    continue
                used[i] = True
                count += count_permutations(nums, used)
                used[i] = False
        return count % MOD

    used = [False] * n
    return count_permutations(nums, used)

def imbalance_number(arr):
    sarr = sorted(arr)
    imbalance = 0
    for i in range(len(sarr) - 1):
        if sarr[i + 1] - sarr[i] > 1:
            imbalance += 1
    return imbalance

def sum_of_imbalance_numbers(nums):
