            total_imbalance += imbalance_number(nums[i:j])
    return total_imbalance

def max_jumps(nums, target):
    n = len(nums)
    dp = [0] * n
    dp[0] = 1
    for i in range(1, n):
        for j in range(i):
            if -target <= nums[i] - nums[j] <= target:
                dp[i] = max(dp[i], dp[j] + 1)
    return dp[-1] if dp[-1] > 0 else -1

def count_complete_subarrays(nums):
