    while mainTank > 0:
        distance += 10
        mainTank -= 1
        if mainTank == 0:
            if additionalTank > 0:
                mainTank += 1
                additionalTank -= 1
    return distance

def longest_even_odd_subarray(nums, threshold):
    max_length = 0
    current_length = 0
    for i in range(len(nums)):
        if nums[i] % 2 == 0:
            current_length = 1
        else:
            current_length = 0
        for j in range(i + 1, len(nums)):
            if nums[j] % 2 == nums[j - 1] % 2:
                break
            if nums[j] <= threshold:
                current_length += 1
            else:
                break
        max_length = max(max_length, current_length)
    return max_length

def count_ways_to_split(nums):
    MOD = 10**9 + 7
    count_ones = 0
    ways = 1
    for num in nums:
        if num == 1:
            count_ones += 1
        else:
            ways = (ways * (count_ones + 1)) % MOD
            count_ones = 0
    return ways

def continuous_subarrays(nums):
    if not nums:
        return 0

    left = 0
    right = 0
    count = 0

    while right < len(nums):
        if nums[right] - nums[left] > 2:
            left += 1
        count += right - left + 1
        right += 1

    return count

def max_non_decreasing_subarray(nums1, nums2):
    n = len(nums1)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if nums1[i - 1] <= nums2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[n][n]

def max_alternating_subarray(nums):
    max_length = -1
    current_length = 1
    for i in range(1, len(nums)):
        if nums[i] == nums[i-1] + 1:
            current_length += 1
        elif nums[i] == nums[i-1] - 1:
            current_length += 1
        else:
            max_length = max(max_length, current_length)
            current_length = 1
    max_length = max(max_length, current_length)
    return max_length

