def is_prime(num):
    if num <= 1:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

def prime_pairs(n):
    pairs = []
    for x in range(2, n // 2 + 1):
        y = n - x
        if is_prime(x) and is_prime(y):
            pairs.append([x, y])
    return sorted(pairs)

def find_min_length_string(a, b, c):
    def is_subsequence(s, t):
        it = iter(s)
        return all(c in it for c in t)

    def find_lexicographically_smallest_string(a, b, c):
        def backtrack(index, current):
            if index == len(a) and index == len(b) and index == len(c):
                return current
            if index == len(a):
                return backtrack(index + 1, current + b)
            if index == len(b):
                return backtrack(index + 1, current + a)
            if index == len(c):
                return backtrack(index + 1, current + a + b)
            if a[index] == b[index]:
                return backtrack(index + 1, current + a[index])
            if b[index] == c[index]:
                return backtrack(index + 1, current + b[index])
            if a[index] == c[index]:
                return backtrack(index + 1, current + a[index])
            return backtrack(index + 1, current + b[index])

        return backtrack(0, "")

    def find_min_length_string_with_constraints(a, b, c):
        def backtrack(index, current):
            if index == len(a) and index == len(b) and index == len(c):
                return current
            if index == len(a):
                return backtrack(index + 1, current + b)
            if index == len(b):
                return backtrack(index + 1, current + a)
            if index == len(c):
                return backtrack(index + 1, current + a + b)
            if a[index] == b[index]:
                return backtrack(index + 1, current + a[index])
            if b[index] == c[index]:
                return backtrack(index + 1, current + b[index])
            if a[index] == c[index]:
                return backtrack(index + 1, current + a[index])
            return backtrack(index + 1, current + b[index])

        return backtrack(0, "")

    def find_min_length_string_with_constraints_and_lexicographical_smallest(a, b, c):
        def backtrack(index, current):
            if index == len(a) and index == len(b) and index == len(c):
                return current
            if index == len(a):
                return backtrack(index + 1, current + b)
            if index == len(b):
                return backtrack(index + 1, current + a)
            if index == len(c):
                return backtrack(index + 1, current + a + b)
            if a[index] == b[index]:
                return backtrack(index + 1, current + a[index])
            if b[index] == c[index]:
                return backtrack(index + 1, current + b[index])
            if a[index] == c[index]:
                return backtrack(index + 1, current + a[index])
            return backtrack(index + 1, current + b[index])

        return backtrack(0, "")

def can_make_all_zero(nums, k):
    if k > len(nums):
        return False

    for i in range(len(nums)):
        if nums[i] > 0:
            for j in range(i, min(i + k, len(nums))):
                nums[j] -= 1

    return all(x == 0 for x in nums)

def min_changes_to_semi_palindrome(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 0
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if length == 2:
                dp[i][j] = 0 if s[i] == s[j] else 1
            else:
                dp[i][j] = min(dp[i + d][j - d] + (length - 2 * d) // 2 for d in range(1, length // 2 + 1) if (length - 2 * d) % 2 == 0)
    return dp[0][n - 1]

def min_changes_to_k_semi_palindromes(s, k):
    n = len(s)
    dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for i in range(1, n + 1):
        for j in range(1, min(i, k) + 1):
            for l in range(i):
                dp[i][j] = min(dp[i][j], dp[l][j - 1] + min_changes_to_semi_palindrome(s[l:i]))
    return dp[n][k]

def split_words(words, separator):
    result = []
    for word in words:
        split_words = word.split(separator)
        for sub_word in split_words:
            if sub_word:
                result.append(sub_word)
    return result

def count_ways(n, x):
    MOD = 10**9 + 7
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        for j in range(1, i + 1):
            if i % j == 0:
                dp[i] = (dp[i] + dp[i // j]) % MOD
    return dp[n]

def min_beautiful_partitions(s):
    def is_power_of_5(n):
        while n % 5 == 0:
            n //= 5
        return n == 1

    dp = [float('inf')] * (len(s) + 1)
    dp[0] = 0

    for i in range(1, len(s) + 1):
        for j in range(i):
            if s[j] == '0':
                continue
            if is_power_of_5(int(s[j:i], 2)):
                dp[i] = min(dp[i], dp[j] + 1)

    return dp[len(s)] if dp[len(s)] != float('inf') else -1

def longestValidSubstring(word, forbidden):
    forbidden_set = set(forbidden)
    max_length = 0
    current_length = 0
    for char in word:
        if char not in forbidden_set:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 0
    return max_length

def final_string(s):
    result = ""
    for char in s:
        if char == 'i':
            result = result[::-1]
        else:
            result += char
    return result

def permute_vowels(s):
    vowels = 'aeiouAEIOU'
    consonants = [c for c in s if c not in vowels]
    vowels_sorted = sorted([c for c in s if c in vowels])
    result = []
    vowel_index = 0
    for c in s:
        if c in vowels:
            result.append(vowels_sorted[vowel_index])
            vowel_index += 1
        else:
            result.append(c)
    return ''.join(result)

def max_beauty(nums, k):
    nums.sort()
    left, right = 0, len(nums) - 1
    max_beauty = 1
    while left <= right:
        if nums[left] + k >= nums[right]:
            max_beauty = max(max_beauty, right - left + 1)
            left += 1
        else:
            right -= 1
    return max_beauty

def max_score(nums, x):
    if not nums:
        return 0

    max_score = nums[0]
    current_score = nums[0]

    for i in range(1, len(nums)):
        if nums[i] % 2 == nums[i-1] % 2:
            current_score += nums[i]
        else:
            current_score += nums[i] - x

        max_score = max(max_score, current_score)

    return max_score

def max_digit(num):
    return max(int(digit) for digit in str(num))

def max_pair_sum(nums):
    max_sum = -1
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if max_digit(nums[i]) == max_digit(nums[j]):
                max_sum = max(max_sum, nums[i] + nums[j])
    return max_sum

def count_interesting_subarrays(nums, modulo, k):
    count = 0
    prefix_count = {0: 1}
    current_count = 0

    for num in nums:
        if num % modulo == k:
            current_count += 1
        current_count %= modulo

        if current_count - k in prefix_count:
            count += prefix_count[current_count - k]

