    def count_up_to(num):
        if num == "0":
            return 1

        dp = [[0] * 10 for _ in range(len(num) + 1)]
        dp[0][0] = 1

        for i in range(1, len(num) + 1):
            for j in range(10):
                if j == 0:
                    dp[i][j] = dp[i-1][j]
                elif j == 9:
                    dp[i][j] = dp[i-1][j]
                else:
                    dp[i][j] = (dp[i-1][j] + dp[i-1][j-1]) % MOD

        return dp[-1][-1]

