def max_sum_almost_unique_subarray(nums, m, k):
    from collections import defaultdict

    max_sum = 0
    current_sum = 0
    distinct_elements = defaultdict(int)

    for i in range(len(nums)):
        current_sum += nums[i]
        distinct_elements[nums[i]] += 1

        if len(distinct_elements) >= m:
            max_sum = max(max_sum, current_sum)

        if i >= k - 1:
            current_sum -= nums[i - (k - 1)]
            distinct_elements[nums[i - (k - 1)]] -= 1
            if distinct_elements[nums[i - (k - 1)]] == 0:
                del distinct_elements[nums[i - (k - 1)]]

    return max_sum

