    n, m = len(grid), len(grid[0])
    product = [[1] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if i == 0 and j == 0:
                product[i][j] = 1
            elif i == 0:
                product[i][j] = (product[i][j-1] * grid[i][j]) % MOD
            elif j == 0:
                product[i][j] = (product[i-1][j] * grid[i][j]) % MOD
            else:
                product[i][j] = (product[i-1][j] * product[i][j-1] * grid[i][j]) % MOD

    return product

