        return str(x) == str(x)[::-1]

    def find_closest_palindrome(x):
        if is_palindrome(x):
            return x

        lower = x - 1
        upper = x + 1

        while not is_palindrome(lower):
            lower -= 1

        while not is_palindrome(upper):
            upper += 1

        return min(lower, upper)

    palindromes = set(find_closest_palindrome(x) for x in nums)

    def calculate_cost(target):
        return sum(abs(num - target) for num in nums)

    return min(calculate_cost(palindrome) for palindrome in palindromes)

