def max_candies(H, W, T, grid):
    from collections import deque

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    start = None
    goal = None
    candies = set()

    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'G':
                goal = (i, j)
            elif grid[i][j] == 'o':
                candies.add((i, j))

    queue = deque([(start[0], start[1], 0)])
    visited = set()
    visited.add((start[0], start[1]))

    while queue:
        x, y, moves = queue.popleft()

        if moves > T:
            continue

        if (x, y) == goal:
            return len(candies)

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] != '#' and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, moves + 1))

    return -1

