def min_operations_to_get_1_and_M(N, M, sets):
    from collections import defaultdict

    # Create a graph where each node represents a set
    graph = defaultdict(list)
    for i in range(N):
        for j in range(1, M+1):
            if j in sets[i]:
                graph[i].append(j)

    # Find the connected components
    visited = set()
    components = []
    for i in range(N):
        if i not in visited:
            component = []
            stack = [i]
            while stack:
                node = stack.pop()
                if node not in visited:
                    visited.add(node)
                    component.append(node)
                    for neighbor in graph[node]:
                        if neighbor not in visited:
                            stack.append(neighbor)
            components.append(component)

    # Check if there is a component that contains both 1 and M
    for component in components:
        if 1 in component and M in component:
            return len(component) - 1

    return -1

