import math

def is_infected(N, D, coordinates):
    infected = [False] * N
    infected[0] = True
    queue = [0]
    while queue:
        current = queue.pop(0)
        for neighbor in range(N):
            if neighbor == current:
                continue
            distance = math.sqrt((coordinates[current][0] - coordinates[neighbor][0])**2 + (coordinates[current][1] - coordinates[neighbor][1])**2)
            if distance <= D and not infected[neighbor]:
                infected[neighbor] = True
                queue.append(neighbor)
