    A = list(map(int, input[1:N+1]))
    Q = int(input[N+1])
    queries = [(int(input[N+2+2*i]), int(input[N+3+2*i])) for i in range(Q)]

    # Precompute the sleep sessions
    sleep_sessions = []
    for i in range(1, (N-1)//2 + 1):
        sleep_sessions.append((A[2*i], A[2*i+1]))

    # Process each query
    for l, r in queries:
        total_sleep = 0
        for start, end in sleep_sessions:
            if start <= l and end >= r:
                total_sleep += end - start
        print(total_sleep)

