def count_ways(N, M):
    if N == 1:
        return M
    if N == 2:
        return M * (M - 1)

    dp = [[0] * M for _ in range(N)]
    dp[0][0] = 1

    for i in range(1, N):
        for j in range(M):
            for k in range(M):
                if j != k:
                    dp[i][j] = (dp[i][j] + dp[i-1][k]) % MOD

    return dp[N-1][0]

