def shift_outer_squares(grid):
    N = len(grid)
    outer_squares = []
    for i in range(N):
        for j in range(N):
            if i == 0 or i == N-1 or j == 0 or j == N-1:
                outer_squares.append((i, j))

    shifted_squares = []
    for i, j in outer_squares:
        if i == 0:
            shifted_squares.append((i, j+1))
        elif i == N-1:
            shifted_squares.append((i-1, j))
        elif j == 0:
            shifted_squares.append((i, j+1))
        elif j == N-1:
            shifted_squares.append((i-1, j-1))

    shifted_grid = [[0] * N for _ in range(N)]
    for i, j in shifted_squares:
        shifted_grid[i][j] = grid[shifted_squares.index((i, j))]

    return shifted_grid

