def nand(a, b):
    return 1 if a == 0 and b == 0 else 0

def sum_of_nand(S):
    N = len(S)
    dp = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(1, N + 1):
        dp[i][i] = int(S[i - 1])
    for i in range(1, N):
        for j in range(i + 1, N + 1):
            dp[i][j] = nand(dp[i][j - 1], int(S[j - 1]))
    return sum(dp[i][j] for i in range(1, N + 1) for j in range(i, N + 1))

