def find_cycle(N, A):
    visited = [False] * (N + 1)
    parent = [0] * (N + 1)

    def dfs(v):
        visited[v] = True
        for u in A[v]:
            if not visited[u]:
                parent[u] = v
                dfs(u)
            elif parent[v] != u:
                return False
        return True

    for v in range(1, N + 1):
        if not visited[v]:
            if dfs(v):
                break

    cycle = []
    u = v
    while True:
        cycle.append(u)
        u = parent[u]
        if u == v:
            break

    cycle.reverse()
    print(len(cycle))
    print(' '.join(map(str, cycle)))

