def count_ice_squares(N, M, grid):
    ice_squares = set()

    # Start from (2,2) and explore all possible paths
    for i in range(2, N):
        for j in range(2, M):
            if grid[i][j] == '.':
                ice_squares.add((i, j))

                # Explore all four directions
                for di, dj in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                    ni, nj = i + di, j + dj
                    while 0 <= ni < N and 0 <= nj < M and grid[ni][nj] == '.':
                        ice_squares.add((ni, nj))
                        ni += di
                        nj += dj

    return len(ice_squares)

