def count_parenthesis_strings(s):
    n = len(s)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(i + 1):
            if s[i - 1] == '(':
                dp[i][j] = dp[i - 1][j - 1]
            elif s[i - 1] == ')':
                if j > 0:
                    dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[n][n]

