def find_strongest_programmer(N, M, relations):
    # Create a graph to represent the superiority relations
    graph = {i: set() for i in range(1, N+1)}
    for A, B in relations:
        graph[A].add(B)
        graph[B].add(A)

    # Check if there is a unique strongest programmer
    strongest_candidates = set()
    for i in range(1, N+1):
        if len(graph[i]) == N-1:
            strongest_candidates.add(i)

    if len(strongest_candidates) == 1:
        return strongest_candidates.pop()
    else:
        return -1

