def max_weight_edges(N, D):
    dp = [[0] * (1 << N) for _ in range(N)]
    for i in range(N):
        dp[i][1 << i] = D[i][i]
    for mask in range(1 << N):
        for i in range(N):
            if mask & (1 << i):
                for j in range(N):
                    if not (mask & (1 << j)):
                        new_mask = mask | (1 << j)
                        dp[j][new_mask] = max(dp[j][new_mask], dp[i][mask] + D[i][j])
    return max(dp[i][(1 << N) - 1] for i in range(N))

