def min_cost_to_achieve_goal(N, K, P, plans):
    dp = [[float('inf')] * (P + 1) for _ in range(K + 1)]
    dp[0][0] = 0

    for cost, *params in plans:
        for j in range(K, 0, -1):
            for p in range(P, 0, -1):
                if dp[j - 1][p - 1] != float('inf'):
                    dp[j][p] = min(dp[j][p], dp[j - 1][p - 1] + cost)

    result = dp[K][P]
    if result == float('inf'):
        return -1
    return result

