def find_possible_strings(N, T_prime, strings):
    possible_indices = []
    for i, string in enumerate(strings, start=1):
        if string == T_prime:
            possible_indices.append(i)
        elif len(string) == len(T_prime) + 1:
            for j in range(len(string)):
                if string[:j] + string[j+1:] == T_prime:
                    possible_indices.append(i)
        elif len(string) == len(T_prime) - 1:
            for j in range(len(string)):
                if string[:j] + string[j+1:] == T_prime:
                    possible_indices.append(i)
        elif len(string) == len(T_prime) and string[0] != T_prime[0]:
            for j in range(len(string)):
                if string[j] != T_prime[j]:
                    possible_indices.append(i)
    return possible_indices

