    dp = [[float('inf')] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = 0
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            if i == j:
                continue
            dp[i][j] = min(dp[i][j], dp[i][j-1] + D[i-1][j-1] * A)
            dp[i][j] = min(dp[i][j], dp[i-1][j] + D[i-1][j-1] * B + C)
