def min_cost_to_monitor_sections(N, D, L, C, K):
    dp = [[float('inf')] * (K[0] + 1) for _ in range(N + 1)]
    dp[0][0] = 0
    for i in range(1, N + 1):
        for j in range(K[0] + 1):
            dp[i][j] = dp[i-1][j]
            for k in range(1, K[0] + 1):
                if j + k <= K[0]:
                    dp[i][j] = min(dp[i][j], dp[i-1][j] + C[0] * k)
            for k in range(1, K[1] + 1):
                if j + k <= K[1]:
                    dp[i][j] = min(dp[i][j], dp[i-1][j] + C[1] * k)
    return dp[N][K[0]] + dp[N][K[1]]

