def min_operations_to_match(H, W, A, B):
    if A == B:
        return 0

    # Check if it's possible to make A identical to B
    for i in range(H):
        for j in range(W):
            if A[i][j] != B[i][j]:
                return -1

    # Count the number of swaps needed
    swaps = 0
    for i in range(H-1):
        for j in range(W-1):
            if A[i][j] > A[i+1][j] and A[i][j] > A[i+1][j+1]:
                A[i], A[i+1] = A[i+1], A[i]
                swaps += 1
            elif A[i][j] < A[i+1][j] and A[i][j] < A[i+1][j+1]:
                A[i], A[i+1] = A[i+1], A[i]
                swaps += 1

    return swaps

