    potion_count = [0] * (N + 1)
    monster_count = [0] * (N + 1)
    actions = []

    for t, x in events:
        if t == 1:
            potion_count[x] += 1
            actions.append(1)
        elif t == 2:
            if potion_count[x] > 0:
                potion_count[x] -= 1
                actions.append(0)
