MOD = 998244353

def find_connected_components(grid, H, W):
    visited = [[False] * W for _ in range(H)]
    components = 0
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#' and not visited[i][j]:
                components += 1
                stack = [(i, j)]
                while stack:
                    x, y = stack.pop()
                    visited[x][y] = True
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] == '#' and not visited[nx][ny]:
                            stack.append((nx, ny))
    return components

