def min_moves_to_meet(N, grid):
    player1 = None
    player2 = None
    for i in range(N):
        for j in range(N):
            if grid[i][j] == 'P':
                if player1 is None:
                    player1 = (i, j)
                else:
                    player2 = (i, j)

    moves = 0
    while player1 != player2:
        moves += 1
        dx, dy = player1[0] - player2[0], player1[1] - player2[1]
        if dx == 0 and dy == 0:
            break
        if dx == 0:
            player1 = (player1[0], player1[1] + dy)
        elif dy == 0:
            player1 = (player1[0] + dx, player1[1])
        elif dx > 0:
            player1 = (player1[0] - dx, player1[1])
        elif dx < 0:
