def count_possible_positions(H, W, N, T, grid):
    def is_valid(x, y):
        return 1 <= x <= H and 1 <= y <= W and grid[x-1][y-1] == '.'

    def move(x, y, direction):
        if direction == 'L':
            return x, y - 1
        elif direction == 'R':
            return x, y + 1
        elif direction == 'U':
            return x - 1, y
        elif direction == 'D':
            return x + 1, y

    def bfs(x, y, visited):
        queue = [(x, y)]
        while queue:
            cx, cy = queue.pop(0)
            if (cx, cy) == (H, W):
                return True
            if visited[cx][cy]:
                continue
            visited[cx][cy] = True
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = move(cx, cy, (dx, dy))
                if is_valid(nx, ny):
                    queue.append((nx, ny))
        return False

    visited = [[False] * (W + 1) for _ in range(H + 1)]
    possible_positions = 0

    for i in range(1, H + 1):
        for j in range(1, W + 1):
            if grid[i-1][j-1] == '.' and bfs(i, j, visited):
                possible_positions += 1

    return possible_positions

