def can_place_tiles(N, H, W, tiles):
    grid = [[0] * W for _ in range(H)]

    def place_tile(x, y, a, b):
        for i in range(a):
            for j in range(b):
                grid[x + i][y + j] = 1

    def remove_tile(x, y, a, b):
        for i in range(a):
            for j in range(b):
                grid[x + i][y + j] = 0

    def is_valid(x, y):
        return 0 <= x < H and 0 <= y < W and grid[x][y] == 0

    def backtrack(index):
        if index == N:
            return True

        a, b = tiles[index]
        for i in range(H):
            for j in range(W):
                if is_valid(i, j):
                    place_tile(i, j, a, b)
                    if backtrack(index + 1):
                        return True
                    remove_tile(i, j, a, b)
        return False

    return backtrack(0)

