    def is_black(x, y):
        if x == 0.5 or y == 0.5:
            return True
        if x % 2 == 0 and y % 2 == 0:
            return True
        if x + y % 2 == 0:
            return True
        return False

    def is_white(x, y):
        if x == 0.5 or y == 0.5:
            return False
        if x % 2 == 0 and y % 2 == 0:
            return False
        if x + y % 2 == 0:
            return False
        return True

    black_area = 0
    for x in range(A, C):
        for y in range(B, D):
            if is_black(x, y):
                black_area += 1
    return 2 * black_area

