def max_strength(nums, k):
    n = len(nums)
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            dp[i][j] = dp[i - 1][j]
            if j > 1:
                dp[i][j] = max(dp[i][j], dp[i - 1][j - 1] + nums[i - 1] * j - nums[i - j] * (j - 1))
            if j > 2:
                dp[i][j] = max(dp[i][j], dp[i - 1][j - 2] + nums[i - 1] * j - nums[i - j] * (j - 2) + nums[i - j - 1] * (j - 3))
            if j > 3:
                dp[i][j] = max(dp[i][j], dp[i - 1][j - 3] + nums[i - 1] * j - nums[i - j] * (j - 3) + nums[i - j - 1] * (j - 4) - nums[i - j - 2] * (j - 5))
            if j > 4:
                dp[i][j] = max(dp[i][j], dp[i - 1][j - 4] + nums[i - 1] * j - nums[i - j] * (j - 4) + nums[i - j - 1] * (j - 5) - nums[i - j - 2] * (j - 6) + nums[i - j - 3] * (j - 7))
            if j > 5:
                dp[i][j] = max(dp[i][j], dp[i - 1][j - 5] + nums[i - 1] * j - nums[i - j] * (j - 5) + nums[i - j - 1] * (j - 6) - nums[i - j - 2] * (j - 7) + nums[i - j - 3] * (j - 8) - nums[i - j - 4] * (j - 9))
    return dp[n][k]

