    dp = [float('inf')] * (k + 1)
    dp[0] = 0
    for coin in coins:
        for i in range(coin, k + 1):
            dp[i] = min(dp[i], dp[i - coin] + coin)
    return dp[k]

def min_sum_of_values(nums, andValues):
    n = len(nums)
    m = len(andValues)

    if n != m:
        return -1

    dp = [[float('inf')] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = 0

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            for k in range(j):
                if (nums[k] & nums[k + 1] & ... & nums[j - 1]) == andValues[i - 1]:
                    dp[i][j] = min(dp[i][j], dp[i - 1][k] + nums[j - 1])

    return dp[m][n] if dp[m][n] != float('inf') else -1

