        comp += str(count) + c
    return comp

def max_sum_non_adjacent(nums):
    if not nums:
        return 0
    incl = 0
    excl = 0
    for num in nums:
        new_excl = max(incl, excl)
        incl = excl + num
        excl = new_excl
    return max(incl, excl)

def max_sum_non_adjacent_after_queries(nums, queries):
    MOD = 10**9 + 7
    for pos, x in queries:
        nums[pos] = x
        ans = max_sum_non_adjacent(nums)
        ans %= MOD
        ans += ans
    return ans

def min_partitions(s):
    def is_balanced(sub):
        return len(sub) == len(set(sub))

    def backtrack(start, end):
        if start == end:
            return 1
        min_partitions = float('inf')
        for i in range(start, end):
            if is_balanced(s[start:i+1]):
                min_partitions = min(min_partitions, 1 + backtrack(i+1, end))
        return min_partitions

    return backtrack(0, len(s))

def powerful_array(x):
    powers = []
    while x > 0:
        power = 1
        while power <= x:
            power *= 2
            if power > x:
                break
        powers.append(power)
        x -= power
    return powers

def product_of_range(from_i, to_i, mod_i):
    powers = []
    for i in range(from_i, to_i + 1):
        powers.extend(powerful_array(i))
    product = 1
    for power in powers:
        product *= power
        product %= mod_i
    return product

def answer_queries(queries):
    results = []
    for from_i, to_i, mod_i in queries:
        results.append(product_of_range(from_i, to_i, mod_i))
    return results

def find_xor_of_duplicates(nums):
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1
    duplicates = [num for num, count in counts.items() if count == 2]
    return reduce(lambda x, y: x ^ y, duplicates)

def find_occurrences(nums, queries, x):
    occurrences = []
    for num in nums:
        if num == x:
            occurrences.append(nums.index(num))
    return [occurrences[i] for i in range(len(queries)) if i < len(occurrences) and queries[i] <= len(occurrences)]
